package com.lawportal.litigation.controller;

import com.lawportal.litigation.dto.LegalCaseResponseDto;
import com.lawportal.litigation.entity.LegalCase;
import com.lawportal.litigation.repository.LegalCaseRepository;
import com.lawportal.litigation.service.EvidenceFilterService;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/litigation/cases")
public class LegalCaseController {

    private final LegalCaseRepository caseRepository;
    private final EvidenceFilterService evidenceFilterService;

    public LegalCaseController(LegalCaseRepository caseRepository, EvidenceFilterService evidenceFilterService) {
        this.caseRepository = caseRepository;
        this.evidenceFilterService = evidenceFilterService;
    }

    @GetMapping("/{caseId}")
    public ResponseEntity<LegalCaseResponseDto> getCaseDossier(
            @PathVariable Long caseId,
            Authentication authentication) {
        LegalCase legalCase = caseRepository.findById(caseId)
                .orElseThrow(() -> new IllegalArgumentException("Legal case not found"));
        var allowedEvidence = evidenceFilterService.filterForCounsel(legalCase.getEvidenceItems(), authentication.getName());
        LegalCaseResponseDto dto = new LegalCaseResponseDto(
                legalCase.getId(),
                legalCase.getCaseNumber(),
                legalCase.getTitle(),
                allowedEvidence
        );
        return ResponseEntity.ok(dto);
    }
}
